package com.cognizant.gateway;
import org.slf4j.*; import org.springframework.boot.SpringApplication; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.cloud.gateway.filter.*; import org.springframework.context.annotation.Bean; import reactor.core.publisher.Mono;
@SpringBootApplication public class ApiGatewayApplication { public static void main(String[] args) { SpringApplication.run(ApiGatewayApplication.class,args); } @Bean GlobalFilter requestLogFilter() { Logger log=LoggerFactory.getLogger("gateway.requests"); return (exchange,chain) -> { log.info("{} {}",exchange.getRequest().getMethod(),exchange.getRequest().getURI()); return chain.filter(exchange).then(Mono.fromRunnable(() -> log.info("status={}",exchange.getResponse().getStatusCode()))); }; } }
